        Verse(book = "Pwovèb", chapter = 4, verseNumber = 16, text = "Mechan yo p'ap dòmi toutotan yo pa fè sa ki mal. Dòmi pa ka pran yo si yo pa rive fè sa yo vle fè a.", bookId = 20),
