        Verse(book = "Pwovèb", chapter = 4, verseNumber = 18, text = "Chemen moun k'ap mache dwat yo tankou solèy k'ap leve. Chak lè, l'ap vin pi klere jouk li fin jou nèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 4, verseNumber = 19, text = "Chemen moun mechan yo fè nwa kou lannwit. Yo pa ka wè sou kisa y'ap bite.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 4, verseNumber = 20, text = "Pitit mwen, louvri lespri ou pou ou konprann byen sa m'ap di ou la a. Louvri zòrèy ou pou ou koute pawòl k'ap soti nan bouch mwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 4, verseNumber = 21, text = "Pa janm kite yo soti devan je ou. Kenbe yo nan kè ou. Pa janm bliye yo.", bookId = 20),
