        Verse(book = "Pwovèb", chapter = 4, verseNumber = 24, text = "Pa janm kite manti soti nan bouch ou, ni move pawòl, ni mo deplase.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 4, verseNumber = 25, text = "Gade dwat devan ou. Kenbe je ou fikse sou chemen ki dwat devan ou lan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 4, verseNumber = 26, text = "Chache konnen byen sa w'ap fè. Konsa, tou sa w'ap fè ap mache byen pou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 4, verseNumber = 27, text = "Pa vire ni adwat ni agoch. Pa lage kò ou nan fè sa ki mal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 1, text = "Pitit mwen, louvri lespri ou pou koute sa m'ap di ou, mwen menm ki gen bon konprann. Louvri zòrèy ou pou ou tande konsèy m'ap ba ou, mwen menm ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 2, text = "Konsa, w'a konnen jan pou ou kondi tèt ou byen. Pawòl ki soti nan bouch ou va moutre jan ou se moun ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 3, text = "Bouch madanm lòt moun ka dous kou siwo myèl, pawòl ka koule nan bouch yo tankou dlo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 4, text = "Men, lè tout bagay fini, bouch li anmè kou fyèl, lang li file tankou kouto de bò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 5, text = "L'ap mennen ou kote mò yo ye a. Tou sa l'ap fè se pou touye ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 6, text = "Li p'ap chache chemen lavi. L'ap pwonmennen toupatou, li pa konnen kote li prale.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 7, text = "Koulye a, pitit mwen yo, koute m' byen. Pa janm bliye sa m' pral di nou la a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 8, text = "Rete lwen yon fanm konsa. Pa janm pwoche bò pòt lakay li,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 9, text = "pou fanm deyò pa fini avè ou, pou ou pa fè nèg ankòlè touye ou anvan lè ou!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 10, text = "Si se pa sa, se etranje ki va pran tout byen ou yo. Se lòt moun ki va jwi tou sa ou te travay fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 11, text = "Lè w'a prèt pou ou mouri, w'a kouche sou kabann ou ap plenn. Maladi ap manje ou nan tout kò ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 12, text = "Lè sa a, w'a di: Poukisa mwen pa t' vle kite yo rale zòrèy mwen?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 13, text = "Mwen pa t' vle koute moun ki t'ap moutre m' sa pou m' fè. Mwen pa t' louvri zòrèy mwen lè yo t'ap pale m'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 14, text = "Yon ti kras ankò, mwen t'ap nan tout kalite malè. La, devan tout moun, mwen t'ap pèdi repitasyon m'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 15, text = "Bwè dlo nan kannari ou. Se ak madanm ou ase pou ou rete.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 16, text = "Pa fè pitit ak fanm deyò, pou san ou pa trennen nan lari.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 17, text = "Se pou pitit ou grandi anndan lakay ou. Yo pa ka ap sèvi ou pou y'ap sèvi moun deyò tou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 18, text = "Fè kè ou kontan ak madanm ou. Pran plezi ou ak madanm ou renmen depi lè ou te jenn lan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 19, text = "L'ap bèl, l'ap anfòm tankou nègès banda. Se pou karès li yo toujou fè kè ou kontan, se pou ou toujou renmen fè lamou ak li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 20, text = "Pitit mwen, poukisa pou ou renmen yon lòt fanm? Poukisa pou ou kite madanm ou pou madanm lòt moun?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 21, text = "Seyè a wè tou sa w'ap fè. Kote ou pase, je l' sou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 22, text = "Mechanste mechan yo se yon pèlen pou pwòp tèt yo. Sa yo pare pou lòt moun, se yo menm li rive.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 5, verseNumber = 23, text = "Y'ap mouri paske yo pa konn kontwole tèt yo. Y'ap peri paske yo fin pèdi tèt yo nèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 1, text = "Pitit mwen, si ou pwomèt pou ou reskonsab dèt yon zanmi ou fè, si ou bay pawòl ou pou lajan yon lòt moun prete,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 2, text = "si yo pran pawòl ki soti nan bouch ou pou mele ou, si pwomès ou te fè yo tounen yon pèlen pou ou,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 3, text = "ay, pitit mwen! men sa pou ou fè pou ou wete tèt ou nan traka sa a. Kouri al jwenn zanmi ou lan, kenbe l' kout.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 4, text = "Pa dòmi sou sa. Pa kite sa trennen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 5, text = "Degaje ou chape kò ou anba men l', tankou kabrit k'ap chape kò l' anba men kaptè, tankou zwazo k'ap bat pou l' sove nan men chasè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 6, text = "Ou menm parese, al pran leson nan men foumi yo. Ale wè jan y'ap viv pou ou manyè konprann lavi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 7, text = "Yo pa bezwen moun pou di yo sa pou yo fè. Yo pa bezwen moun pou veye yo, ni pou ba yo lòd.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 8, text = "Men, yo pase mwa chalè ap fè pwovizyon. Nan tan rekòt, yo ranmase manje mete la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 9, text = "Parese, kilè w'a sispann pase tout jounen ou kouche sou do? Kilè w'a souke kò ou leve sot nan dòmi?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 10, text = "W'ap di: Kite m' fè yon ti dòmi. Kite m' fè yon ti kabicha non. M'ap lonje kò m' pou m' pran yon ti repo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 11, text = "Antan w'ap dòmi an, san ou pa konnen, se pòv w'ap vin pi pòv. Grangou ap tonbe sou ou tankou yon vòlè nan gran chemen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 12, text = "Mechan yo fin deprave. Y'ap mache bay manti toupatou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 13, text = "Y'ap twenzi je yo sou moun, y'ap peze gwo zòtèy yo atè. Y'ap fè siy ak dwèt yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 14, text = "Se move lide ase ki nan kè yo, yo toujou sou plan. Kote yo pase y'ap pouse dife.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 15, text = "Se poutèt sa, y'ap rete konsa y'ap fini, y'ap glise tonbe san yo p'ap ka leve ankò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 16, text = "Gen sis bagay Seyè a pa vle wè. Sa m'ap di la a: Gen menm sèt bagay li pa ka sipòte:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 17, text = "Se moun k'ap gonfle lestonmak yo sou moun, se moun k'ap bay manti, se moun k'ap touye moun inonsan,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 18, text = "se moun k'ap fè move lide nan tèt yo pou fè mechanste, se moun ki toujou pare pou fè sa ki mal,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 19, text = "se fo temwen k'ap bay manti sou moun, se moun k'ap mete frè ak zanmi dozado.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 20, text = "Pitit mwen, toujou fè sa papa ou di ou fè. Pa janm bliye sa manman ou te moutre ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 21, text = "Kenbe pawòl yo nan kè ou, pa janm bliye yo. Mete yo nan kou ou tankou yon kolye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 22, text = "Pawòl sa yo va moutre ou bon chemen nan tou sa w'ap fè. Y'ap pwoteje ou lè w'ap dòmi lannwit. Y'a ba ou konsèy lè je ou klè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 23, text = "Pawòl sa yo ap tankou yon lanp pou ou. Sa yo moutre ou ap tankou yon limyè nan lavi ou. Lè y'ap korije ou, lè y'ap rale zòrèy ou, se moutre y'ap moutre ou chemen lavi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 24, text = "Y'ap fè ou rete lwen fanm k'ap twonpe mari yo, pou ou pa pran nan pawòl dous madan marye ki nan dezòd.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 25, text = "Yo te mèt bèl kou yo bèl, pa kite yo pran tèt ou. Pa kite yo pran tèt ou lè y'ap fè je dou ba ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 26, text = "Yon jennès ka koute yon kraze kòb. Men, yon fanm adiltè dèyè pou l' pran tou sa ou genyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 27, text = "Ou pa ka sere dife anndan rad sou ou pou rad la pa boule.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 28, text = "Ou pa ka mache sou chabon dife pou pye ou pa boule.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 29, text = "Konsa tou, se yon gwo danje pou ou kouri dèyè fanm yon lòt gason. Depi ou manyen yon fanm konsa, ou gen pou ou peye pou sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 30, text = "Menm lè yon vòlò vòlò paske li grangou, se pa sa ki di li pa vòlò pou sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 31, text = "Si yo bare l', y'ap fè l' peye sèt fwa lavalè sa l' pran an. Y'a fè l' bay tou sa li gen lakay li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 32, text = "Men, yon nonm ki fè adiltè, se moun fou li ye, se detwi l'ap detwi tèt li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 33, text = "L'ap pran baton. Y'ap pase l' anba kont betiz, l'ap toujou wont pou sa l' fè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 34, text = "Lè yon mari ap fè jalouzi pou madanm li, nanpwen move tankou l'. Jou li mete men sou nèg la, pa gen anyen li p'ap fè l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 6, verseNumber = 35, text = "Li p'ap asepte lajan. Nanpwen kado ki pou fè l' bliye sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 1, text = "Pitit mwen, chonje sa m'ap moutre ou la a. Pa janm bliye sa m'ap di ou pou fè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 2, text = "Si ou fè sa m'ap di ou pou fè a, w'a viv. Konsidere sa m' moutre ou la tankou de grenn je nan tèt ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 3, text = "Mete li nan tout dwèt ou tankou bag, kenbe li nan kè ou pou ou pa janm bliye l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 4, text = "Konsidere konesans tankou sè ou. Konsidere bon konprann tankou pi bon zanmi ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 5, text = "Y'ap fè ou rete lwen madanm lòt moun. Yo p'ap kite ou pran nan pawòl dous madan marye ki nan dezòd.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 6, text = "Yon jou, antan mwen nan fennèt lakay mwen, mwen t'ap gade nan fant jalouzi a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 7, text = "Mwen wè anpil jenn gason san esperyans nan lavi. Te gen yonn ladan yo menm ki te fin fou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 8, text = "Li t'ap mache nan lari a, li rive bò kay yon fanm. Konsa, konsa, li pran chemen ki mennen kay fanm lan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 9, text = "Le sa a solèy te kouche, te fin fè nwa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 10, text = "Madanm lan menm vin kontre li. Li te abiye tankou yon jennès, ak tout plan l' dèyè tèt li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 11, text = "Fanm lan te gen je chèch, li pa t' wont anyen. Li pa t' kapab rete chita lakay li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 12, text = "Li toupatou nan lari, sou laplas, nan tout kalfou. L'ap veye, je l' toupatou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 13, text = "Li pase bra l' nan kou ti jennonm lan. Li bo li, li klere je l' nan je l', li di l':", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 14, text = "Mwen te gen pou m' ofri yon bèt pou yo touye pou di Bondye mèsi. Se jòdi a mwen kit ak angajman mwen an.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 15, text = "Se poutèt sa, mwen vin kontre ou. Mwen t'ap chache ou, mwen jwenn ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 16, text = "Mwen ranje kabann mwen ak bon jan dra. Mwen mete bèl dra koulè ki soti peyi Lejip sou kabann mwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 17, text = "Mwen fè kabann mwen santi bon. Mwen vide odè flè jasmen, womaren ak kannèl sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 18, text = "Vini non! Ann al damou jouk li jou. Annou pran plezi nou. Ann fè doudous jouk nou sou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 19, text = "Mari m' pa la, li pati, li al fè yon vwayaj byen lwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 20, text = "Li pati ak anpil lajan nan pòch li. Li p'ap tounen anvan kenz jou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 21, text = "Se konsa, fanm lan fin pran tèt ti jennonm lan. Ak bèl pawòl dous li yo, li fè l' asepte.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 22, text = "Jennonm lan pran swiv li, tankou bèf y'ap mennen labatwa, tankou kabrit yo pran nan pèlen", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 23, text = "k'ap tann yo vin koupe tèt li, tankou zwazo k'ap mache sou pèlen san li pa konnen lavi l' an danje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 24, text = "Koulye a, pitit mwen yo, koute byen. Louvri zòrèy nou, tande sa m'ap di nou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 25, text = "Pa kite kè nou bat pou fanm konsa. Pa kite li fè nou pèdi chemen nou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 26, text = "Li lakòz anpil gason tonbe mouri. Li lakòz anpil vanyan gason pèdi lavi yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 7, verseNumber = 27, text = "Depi ou mete pye lakay li, ou sou chemen lanmò. W'ap desann yon pant k'ap mennen ou tou dwat nan simityè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 1, text = "Tande byen. Sajès ap rele byen fò. Entèlijans ap pale fò pou tout moun tande.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 2, text = "Li kanpe sou tèt ti mòn yo, sou bò wout la, nan mitan kalfou yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 3, text = "L'ap pale byen fò bò pòtay lavil la, sou tout papòt yo, l'ap di:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 4, text = "Nou menm lèzòm, se ak nou m'ap pale. M'ap rele pou tout moun ki sou latè tande.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 5, text = "Nou menm ki pa gen konprann, vin aprann sa ki rele gen bon konprann Nou menm k'ap aji tankou moun fou, vin aprann sa ki rele gen lespri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 6, text = "Louvri zòrèy nou. Mwen pral di pawòl ki konsekan. Tou sa mwen pral di yo se bagay ki dwat.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 7, text = "Sa m' pral di la a se verite. Mwen pa kapab bay manti.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 8, text = "Tou sa ki soti nan bouch mwen, se pawòl ki dwat. Nan sa m' di yo pa gen anyen ki pa vre, pa gen anyen ki kwochi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 9, text = "Yo klè pou moun ki gen bon konprann. Yo kòrèk pou moun ki gen konesans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 10, text = "Pito ou chache gen bon konprann pase pou ou gen lajan. Pito ou chache gen konesans pase pou ou gen pi bon lò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 11, text = "Paske, mwen menm Bon Konprann, mwen pi bon pase boul lò. Pa gen anyen ou ta renmen genyen ki ka konpare avè m'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 12, text = "Mwen menm Bon Konprann, mwen gen lespri. Mwen gen bon tèt pou m' konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 13, text = "Lè yon moun gen krentif pou Bondye, li rayi sa ki mal. Mwen pa vle wè moun lògey ak moun awogan, moun ki gen move kondit ak moun k'ap bay manti.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 14, text = "Se mwen ki bay bon konsèy, ki bay moun ladrès. Mwen gen konprann, mwen gen fòs pouvwa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 15, text = "Se mwen ki bay wa yo ladrès pou yo kòmande. Se mwen ki fè chèf yo pase bon lòd pou pa gen lenjistis.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 16, text = "Se mwen menm ki bay tout chèf yo tèt pou yo kòmande. Se mwen menm ki fè sa tou pou tout lòt chèf yo ansanm ak tout lòt moun k'ap dirije lèzòm.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 17, text = "Mwen renmen moun ki renmen m'. Depi yon moun chache m', fòk li jwenn mwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 18, text = "Mwen bay richès, mwen bay pouvwa. Mwen bay byen k'ap la pou lontan, mwen fè tout bagay byen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 19, text = "Tou sa mwen bay pi bon lontan pase pi bon lò ki genyen. Yo pi bon pase ajan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 20, text = "Mwen fè moun mache dwat devan Bondye. Mwen fè yo mache yon jan pou yo pa fè moun lenjistis.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 21, text = "Lè moun renmen m', mwen ba yo anpil byen. Mwen plen kay yo ak richès.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 22, text = "Seyè a te fè m' lè li te fèk konmanse ak plan travay li. Li te fè m' lontan lontan anvan tout bagay.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 23, text = "Li te fè m' nan konmansman nèt, an premye, anvan tout lòt bagay sou latè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 24, text = "Lè m' te fèk parèt, pa t' ankò gen lanmè. pa t' ankò gen ankenn sous dlo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 25, text = "Lè m' te fèt la, pa t' ankò gen ankenn mòn menm. Ata ti mòn yo pa t' ankò nan plas yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 26, text = "Bondye pa t' ankò fè latè ak jaden. Pa menm premye grenn pousyè tè a pa t' ankò fèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 27, text = "Mwen te la lè li t'ap mete syèl la nan plas li, lè li t'ap trase liy kote syèl la kontre ak latè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 28, text = "Mwen te la lè li t'ap mete nwaj yo nan syèl la, lè li t'ap fè sous dlo pete anba lanmè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 29, text = "Mwen te la lè li t'ap bay dlo lanmè a limit pou l' pa depase, lè li t'ap poze fondasyon tè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 30, text = "Mwen te la bò kote l' ap travay avè l'. Chak jou mwen t'ap fè tout bagay ki te fè l' plezi. Mwen te toujou kontan travay anba je l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 31, text = "Mwen te kontan mache toupatou sou latè. Mwen te pran plezi m' ak lèzòm.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 32, text = "Koulye a, pitit mwen yo, louvri zòrèy nou pou nou tande mwen. Ala bon sa bon pou moun ki fè sa m' di yo fè!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 33, text = "Louvri zòrèy nou pou nou tande sa m'ap moutre nou. N'a vin gen bon konprann. Pa meprize bagay konsa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 34, text = "Ala bon sa bon pou moun ki koute m', pou moun ki chita nan papòt mwen chak jou, pou moun k'ap tann bò poto galeri kay mwen!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 35, text = "Lè yon moun jwenn mwen, se lavi li jwenn. Li antre nan favè Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 8, verseNumber = 36, text = "Men moun ki vire do ban mwen ap fè tèt yo mal. Moun ki rayi m', se moun k'ap mache ak sèkèy yo anba bra yo.", bookId = 20)
