    private fun part2(): List<Verse> = listOf(
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 1, text = "Bon konprann bati kay li, li kanpe l' avèk sèt gwo poto.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 2, text = "Li fè yo pare bon vyann pou fè fèt, li fè bon konpoze ak diven, li ranje tab la byen ranje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 3, text = "Li rele sèvant li yo, li voye yo moute kote ki pi wo nan lavil la pou fè tout moun konnen nouvèl la, pou di yo:", bookId = 20),
