        Verse(book = "Pwovèb", chapter = 9, verseNumber = 5, text = "Vin manje manje mwen an non! Vin bwè bon diven mwen pare a non!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 6, text = "Kite sòt! Vin aprann lavi! Vin mache nan chemen konesans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 7, text = "Si w'ap kouri dèyè yon moun k'ap pase moun nan betiz, l'ap joure ou mete sou li. Si w'ap rale zòrèy yon mechan, l'ap bat ou mete sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 8, text = "Pa janm kouri dèyè yon moun k'ap pase moun nan betiz. L'a rayi ou. Men, si w'ap kouri dèyè yon moun ki gen konprann, l'a gen respè pou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 9, text = "Si ou pale ak yon moun ki gen bon konprann, w'ap fè l' gen plis bon konprann toujou. Plis w'ap moutre yon nonm debyen, plis l'ap mete sou konesans li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 10, text = "Lè ou gen krentif pou Bondye, se lè sa a ou konmanse gen bon konprann. Si ou konnen ki moun Bondye ye, ou gen lespri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 11, text = "Bon konprann ap fè ou viv lontan. L'ap fè ou wè plizyè lanne.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 12, text = "Si ou gen bon konprann, premye moun k'ap pwofite sa se ou menm. Konsa tou, si w'ap pase konesans nan betiz, se ou menm tou k'ap peye konsekans lan pou kont ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 13, text = "Moun sòt, se tankou yon fanm ki pale fò, ki pa konn anyen, ki pa wont anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 14, text = "Li chita sou yon chèz devan papòt lakay li, li kage chèz li kote ki pi wo nan lavil la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 15, text = "L'ap rele moun ki sou wout yo, ki pa sou bò l'. L'ap di yo:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 16, text = "Vini jwenn mwen non, nou menm ki poko konn anyen! Li pale ak moun ki san konprann yo, li di yo:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 17, text = "Dlo kay moun toujou pi fre. Manje deyò toujou gen pi bon gou!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 9, verseNumber = 18, text = "Men, moun ki pran nan pawòl fanm sa a pa konnen lè yo mete pye lakay li se papye lanmò yo yo senyen. Depi yo antre lakay li, yo deja mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 1, text = "Men pwovèb wa Salomon yo: Yon pitit ki gen bon konprann fè kè papa l' kontan. Men, yon pitit san konprann bay manman l' lapenn.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 2, text = "Byen ou rive fè nan move kondisyon p'ap rapòte ou anyen. Men, lè ou serye, ou sove lavi ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 3, text = "Seyè a p'ap kite moun ki mache dwat soufri grangou. Men, l'ap anpeche mechan an jwenn sa li anvi a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 4, text = "Parese fè ou pòv, men travay di fè ou rich.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 5, text = "Yon nonm ki wè lwen ranmase rekòt li lè rekòt la pare. Men, se yon wont pou moun ki pase tou tan rekòt la ap dòmi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 6, text = "benediksyon Bondye ap chita sou yon nonm debyen. Pawòl yon moun mechan p'ap janm kite ou wè jan l' mechan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 7, text = "Y'ap toujou chonje yon nonm debyen, y'a fè lwanj pou li. Men, talè konsa non mechan an ap sèvi jouman.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 8, text = "Moun ki gen bon konprann koute konsèy yo ba li. Men, moun k'ap pale tankou moun fou pa lwen mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 9, text = "Yon nonm serye pa janm bezwen pe anyen. Men, yo gen pou yo bare moun k'ap fè vis.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 10, text = "Moun k'ap twenzi je yo sou moun, se moun k'ap voye wòch kache men. Men, moun ki pale kare anpeche kont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 11, text = "Pawòl ki soti nan bouch moun k'ap mache dwat yo bay lavi. Men, pawòl yon moun mechan p'ap janm kite ou wè jan l' mechan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 12, text = "Lè ou gen renmen nan kè ou, ou padonnen tout peche. Men, lè ou rayi moun, ou toujou ap chache kont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 13, text = "Moun lespri pale bon pawòl. Men, pou moun san konprann, se baton nan dèyè yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 14, text = "Moun ki gen bon konprann toujou ap aprann. Men, lè moun san konprann ap pale, malè pa lwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 15, text = "Byen yon moun rich, se pwoteksyon li. Men, depi yon nonm pòv, nanpwen pwoteksyon pou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 16, text = "Travay moun k'ap mache dwat yo bay lavi. Lajan moun k'ap fe sa ki mal yo se pou malè yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 17, text = "Moun ki koute lè yo rale zòrèy yo ap jwenn chemen lavi. Men, moun ki refize admèt lè yo antò pèdi chemen yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 18, text = "Moun ki rayi moun nan kè yo, se moun ou pa ka fye. Tout moun k'ap mache fè tripotay se moun san konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 19, text = "Plis ou pale anpil, plis ou ka rive fè peche. Lè ou gen bonjan konprann ou kenbe bouch ou fèmen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 20, text = "Pawòl ki soti nan bouch moun k'ap mache dwat, se lò. Men, lide k'ap travay nan tèt yon mechan pa vo anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 21, text = "Pawòl ki soti nan bouch moun k'ap mache dwat ap pwofite anpil moun. Men, moun sòt yo ap mouri, paske yo pa gen konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 22, text = "benediksyon Bondye bay moun richès. Ou te mèt travay di ou pa ka mete anyen sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 23, text = "Lè moun san konprann ap fè sa ki mal, se tankou yon jwèt pou yo. Men, yon moun lespri pran plezi l' nan chache gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 24, text = "Yon moun ki mache dwat, Bondye va ba li tou sa l' ta renmen genyen. Men mechan an, se sa l' pè rive l' la k'ap rive l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 25, text = "Depi move tan pase, mechan yo disparèt lamenm. Men, moun k'ap mache dwat yo ap toujou kanpe fèm.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 26, text = "Pa janm voye parese fè komisyon pou ou. L'ap ennève ou menm jan sitwon fè dan moun gasi, menm jan lafimen fè je moun koule dlo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 27, text = "Krentif pou Bondye fè moun viv lontan. Men, mechan yo mouri anvan lè yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 28, text = "Sa moun k'ap mache dwat yo ap tann lan va rive vre. Men, mechan yo p'ap janm jwenn sa y'ap tann lan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 29, text = "Chemen Bondye se yon pwoteksyon pou moun ki serye. Men, l'ap detwi moun k'ap fè mal yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 30, text = "Yo p'ap janm ka fè moun k'ap mache dwat yo brannen. Men, mechan yo ap disparèt nan peyi a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 31, text = "Lè moun k'ap mache dwat yo ap pale, se bon koze yo bay. Men, moun k'ap pale mal yo ap disparèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 10, verseNumber = 32, text = "Moun k'ap mache dwat yo konn bèl pawòl pou yo di. Men, lang mechan yo, se kouto de bò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 1, text = "Seyè a pa vle wè moun k'ap sèvi ak fo balans. Li kontan ak moun ki sèvi ak bon mezi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 2, text = "Kote ki gen lògèy wont pa lwen. Men, moun ki soumèt devan Bondye, se yo ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 3, text = "Moun k'ap mache dwat yo konnen sa pou yo fè, paske se moun serye yo ye. Men, moun k'ap mache bay moun koutba, yo gen pou yo fini mal, paske se bakonyè yo ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 4, text = "Jou malè, richès pa ka sèvi ou anyen. Men, si ou se moun serye, sa ka sove lavi ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 5, text = "Yon moun k'ap mache dwat ap viv san pwoblèm, paske li serye. Men, mechan yo ap tonbe nan pwòp pèlen mechanste yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 6, text = "Lè yon moun serye fè sa ki dwat, sa ap sove l'. Men, moun k'ap mache bay moun koutba, y'ap pran nan move jwèt y'ap fè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 7, text = "Lè yon mechan mouri, sa l' t'ap tann lan mouri ansanm avè l'. Konfyans li te mete nan byen li yo pa sèvi l' anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 8, text = "Jou malè, moun ki mache dwat ap jwenn pwoteksyon. Sa ki pou ta rive l' la, se mechan an li rive.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 9, text = "Moun ki san respè pou Bondye ap touye moun ak lang yo. Men, konesans ap sove moun k'ap mache dwat yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 10, text = "Lè sa mache pou moun serye yo, tout moun lavil la gen kè kontan. Konsa tou, lè mechan yo mouri, se kontantman pou tout moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 11, text = "Se bèl bagay pou yon lavil lè li gen moun serye ladan l'. Men, mechan yo ap detwi l' ak lang yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 12, text = "Avili yon frè parèy ou, se bagay moun san konprann fè. Yon moun lespri konnen pou l' pe bouch li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 13, text = "Moun k'ap mache fè tripotay mete tout sekrè deyò. Men, moun ki toujou kenbe pawòl yo, kè yo se kòfrefò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 14, text = "Lè pa gen moun ki konn gouvènen, peyi a pa ka mache. Men, lè gen anpil moun k'ap bay bon konsèy, peyi a sove.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 15, text = "Lè ou pwomèt pou ou peye dèt yon moun ou pa konnen, w'a gen pou règrèt sa pita. L'a pi bon pou ou si ou refize bay garanti pou yon lòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 16, text = "Tout moun va fè lwanj yon fanm ki gen bon karaktè. Konsa tou, gason ki gen kouraj nan travay ap jwenn ak kòb li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 17, text = "Lè ou gen bon kè, se yon byen ou fè pou tèt ou. Men, moun ki san pitye yo, se tèt yo y'ap fè tò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 18, text = "Mechan yo kwè y'ap fè benefis. Men, moun k'ap fè sa ki dwat yo toujou jwenn rekonpans yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 19, text = "Yon moun ki soti pou fè sa ki dwat ap toujou viv. Men, moun k'ap chache fè sa ki mal gen pou yo mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 20, text = "Seyè a pa vle wè moun k'ap mache pye gaye. Men, li pran plezi l' ak moun k'ap mache dwat nan chemen yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 21, text = "Wè pa wè, yo gen pou yo pini mechan yo. Men, tout moun k'ap mache dwat yo ap sove.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 22, text = "Yon bèl fanm ki nan dezòd se yon bèl zanno lò nan nen kochon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 23, text = "Lè moun k'ap mache dwat yo jwenn sa yo te vle a, se kontantman pou tout moun. Men, lè se mechan yo ki jwenn sa yo t'ap tann lan, sa pa fè pesonn plezi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 24, text = "Moun ki bay san gad dèyè, sa pa anpeche yo vin pi rich. Men, moun ki penng, se pòv y'ap vin pi pòv.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 25, text = "Lè ou bay ak kè kontan, ou p'ap janm manke anyen. Lè ou manje ak moun, ou pa janm rete grangou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 26, text = "Pèp la ap madichonnen moun k'ap sere manje nan depo pou pri a ka moute. Men, l'ap fè lwanj pou moun k'ap vann manje a nan mache.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 27, text = "Moun k'ap chache fè sa ki byen ap jwenn favè Bondye. Men, moun k'ap kouri dèyè malè, se malè ki pou rive l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 28, text = "Moun ki mete konfyans yo nan byen yo ap tonbe tankou fèy chèch. Men, moun k'ap mache dwat yo ap pouse tankou boujon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 29, text = "Yon nonm ki mete dezòd nan fanmi li, lakòz madanm li ansanm ak tout pitit li yo nan tou sa ki pa bon. Moun san konprann ap toujou esklav moun ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 30, text = "Lè ou mache dwat, sa fè moun viv. Lè ou gen bon konprann, ou sove lòt moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 11, verseNumber = 31, text = "Gade! Moun ki mache dwat jwenn rekonpans yo isit sou latè. Men, nou pa bezwen mande si moun k'ap fè mechanste ak moun k'ap viv nan peche p'ap jwenn ak pa yo tou!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 1, text = "Moun ki renmen yo korije yo, se moun ki toujou vle konnen. Men, moun ki pa renmen yo rale zòrèy yo, se moun san konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 2, text = "Seyè a kontan ak moun k'ap fè sa ki byen. Men, l'ap kondannen moun ki toujou sou plan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 3, text = "Fè mechanste pa bay moun fòs pou yo rete kanpe. Men, moun ki mache dwat p'ap janm brannen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 4, text = "Yon bon madanm se yon lwanj li ye pou mari li. Men, yon madanm ki fè mari l' wont, se tankou yon maladi k'ap manje ou nan zo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 5, text = "Yon nonm serye p'ap janm mete nan tèt li pou l' fè ou lenjistis. Men, mechan yo ap toujou chache twonpe ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 6, text = "Pawòl ki soti nan bouch mechan se pèlen pou touye moun. Men, pawòl ki soti nan bouch moun k'ap mache dwat yo, se delivrans pou moun ki an danje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 7, text = "Rive yon lè, pye mechan yo chape. Ou chache yo, ou pa wè yo. Men, fanmi moun k'ap mache dwat yo ap toujou la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 8, text = "Y'ap fè lwanj moun ki gen konprann. Men, y'ap meprize moun ki malveyan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 9, text = "Pito ou pase pou malere men ou gen manje pou ou manje, pase pou ou pran pòz grannèg ou epi w'ap mouri grangou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 10, text = "Moun ki mache dwat okipe ata zannimo nan lakou yo. Men, mechan yo san zantray.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 11, text = "Moun ki travay jaden ap jwenn manje pou yo manje plen vant yo. Men, moun k'ap pèdi tan yo nan fè bagay san valè, se san konprann yo ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 12, text = "Mechan toujou ap fè gwo lide dèyè bagay mechan parèy yo pran. Men, moun k'ap mache dwat ap fè bagay k'ap rapòte yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 13, text = "Pawòl ki soti nan bouch moun mechan tounen yon pèlen pou yo. Men, moun k'ap mache dwat ap soti nan tout move pa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 14, text = "Rekonpans yon moun chita sou sa li di ak bouch li. Sa ou fè se sa ou wè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 15, text = "Moun sòt toujou konprann sa y'ap fè a byen. Men, moun ki gen bon konprann koute konsèy yo ba yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 16, text = "Lè yon moun san konprann ankòlè, tout moun wè sa lamenm. Men, yon moun veyatif, lè ou fè l' malonèt, li fè tankou li pa konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 17, text = "Lè ou di verite nan tribinal, ou rann lajistis sèvis. Men, temwen k'ap bay manti, se lenjistis l'ap ankouraje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 18, text = "Pawòl moun ki di tou sa ki vin nan bouch yo se kout ponya. Men, pawòl moun ki gen bon konprann se renmèd.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 19, text = "Manti la pou yon ti tan. Men, verite la pou tout tan tout tan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 20, text = "Moun k'ap kalkile jan pou yo fè moun mal, se move kou y'ap chache pote. Men, moun k'ap bay bon konsèy ap gen kè kontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 21, text = "Malè pa janm rive moun k'ap mache dwat. Men, pou mechan yo se apse sou klou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 22, text = "Seyè a pa vle wè moun k'ap manti. Men, li kontan nèt ak moun ki toujou kenbe pawòl yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 23, text = "Moun lespri pa janm nan fè moun wè tou sa yo konnen. Men, moun san konprann ap mache fè moun wè jan yo sòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 24, text = "Travay di fè ou grannèg. Men, parese fè ou rete ak moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 25, text = "Tèt chaje kraze kouraj yon moun. Men, yon bon pawòl fè kè l' kontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 26, text = "Moun ki mache dwat ap toujou moutre zanmi l' bon chemen. Men, mechan an ap fè yo pèdi chemen yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 27, text = "Parese ap toujou rete grangou. Tout richès yon moun se travay li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 12, verseNumber = 28, text = "Fè sa ki dwat, w'a jwenn ak lavi. Fè sa ki mal, w'a jwenn ak lanmò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 1, text = "Yon pitit gason ki gen bon konprann ap koute lè papa l' ap rale zòrèy li. Men, moun k'ap pase moun nan betiz p'ap janm koute lè y'ap fè l' obsèvasyon pou korije l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 2, text = "Rekonpans yon moun chita sou sa li di ak bouch li. Men, moun ki ipokrit renmen fè mechanste.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 3, text = "Veye pawòl ki soti nan bouch ou, w'a pwoteje lavi ou. Moun k'ap prese louvri bouch yo pale ap detwi pwòp tèt yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 4, text = "Parese p'ap janm jwenn sa yo ta renmen genyen. Men, moun k'ap travay di ap jwenn tou sa yo ta renmen genyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 5, text = "Moun k'ap mache dwat pa vle wè moun k'ap bay manti. Men, sa mechan yo ap fè a se yon wont, se yon dezonè pou tèt yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 6, text = "Lè ou toujou fè sa ki byen, lajistis ap pwoteje ou. Men, peche lakòz mechan yo disparèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 7, text = "Gen moun ki pa gen anyen men ki pran pòz moun rich yo. Gen moun ki pran pòz moun pòv yo, epi se yo ki gen fòtin.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 8, text = "Yon moun rich sèvi ak lajan l' pou l' sove lavi l'. Moun ki pòv pa vle tande lè w'ap rele dèyè l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 9, text = "Moun k'ap mache dwat yo tankou lanp k'ap klere byen klere. Men, mechan yo tankou yon lanp ki prèt pou mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 10, text = "Moun awogan yo toujou ap pouse dife. Men, moun ki koute konsèy, se moun ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 11, text = "Lajan ou fè fasil pa lwen fini. Lajan ou fè nan di ap toujou fè pitit.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 12, text = "Lè ou pa jwenn sa ou t'ap tann lan, se bagay ki pou fè ou malad. Men, lè ou jwenn sa ou te anvi a, se lavi pou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 13, text = "Lè ou pa respekte pawòl ki nan lalwa Bondye a, se dèt ou fè. Men, moun ki fè sa lalwa mande yo fè a ap jwenn rekonpans yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 14, text = "Sa moun ki gen bon konprann ap moutre a bay lavi. L'ap ede ou pou ou pa tonbe lè lavi ou an danje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 15, text = "Lè ou gen bon konprann, sa fè moun renmen ou. Men, lè moun pa ka fè ou konfyans, ou nan di.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 16, text = "Tout moun ki gen konprann kalkile byen anvan yo fè yon bagay. Men, moun san konprann yo ap fè ou wè jan yo sòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 17, text = "Yon move komisyonè ap mete moun nan ka. Men, yon komisyonè serye ap bay moun kè poze.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 18, text = "Yon moun ki refize aprann ap toujou pòv, l'ap toujou wont. Men, y'ap respekte moun ki koute lè yo rale zòrèy yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 19, text = "Ala bon sa bon lè ou jwenn sa ou te anvi a! Moun san konprann derefize kite move chemen yo pran an.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 20, text = "Fè zanmi ak moun ki gen konesans, ou menm tou w'a vin gen konesans. Fè zanmi ak moun ki san konprann, ou nan pwoblèm.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 21, text = "Malè ap pousib moun k'ap fè sa ki mal. Men, moun ki mache dwat ap jwenn bon rekonpans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 22, text = "Yon moun ki gen bon kè ap kite byen pou pitit pitit li. Men, richès moun k'ap fè sa ki mal, se moun ki mache dwat yo k'ap jwi li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 23, text = "Jaden malere bay kont manje. Men, lenjistis fè l' mouri grangou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 24, text = "Si ou pè bat pitit gason ou, ou pa renmen l'. Si ou renmen l', se pou ou korije l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 13, verseNumber = 25, text = "Moun k'ap mache dwat toujou gen ase pou yo manje. Men, vant mechan yo pa janm plen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 1, text = "Bon konprann yon fanm fè kay li mache byen. Men, yon fanm sòt ap kraze kay li ak pwòp men li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 2, text = "Moun ki mache dwat, se yo ki gen krentif pou Seyè a. Men, moun k'ap mache kwochi pa pran Bondye pou anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 3, text = "Pawòl nan bouch moun san konprann, se fwèt pou dèyè yo. Men, pawòl nan bouch moun ki gen bon konprann, se pwoteksyon yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 4, text = "Kote ki pa gen bèf pou rale chari pa gen rekòt. Lè bèt ou anfòm w'ap fè bon rekòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 5, text = "Yon bon temwen p'ap bay manti. Yon fo temwen p'ap di verite.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 6, text = "Moun ki gen lògèy plen kè yo, yo mèt chache konesans, yo p'ap janm jwenn li. Men, pou moun ki gen lespri, se bagay fasil.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 7, text = "Pa pwoche bò kote moun san konprann. Se pa anba bouch yo w'ap pran anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 8, text = "Moun ki gen bon konprann konnen sa l'ap fè. Moun sòt mete nan tèt li li konnen, men se tèt li l'ap twonpe.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 9, text = "Moun sòt pran peche sèvi jwèt. Men, moun k'ap mache dwat pare pou rekonèt tò yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 10, text = "Lè ou nan lapenn, se ou ki konnen sa w'ap soufri. Konsa tou, lè kè ou kontan, pesonn pa ka kontan avè ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 11, text = "Fanmi mechan yo gen pou disparèt. Men, fanmi moun k'ap mache dwat yo gen pou devlope.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 12, text = "Chemen ou kwè ki bon an, se li ki mennen tou dwat nan lanmò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 13, text = "Ou mèt ap ri, kè ou ka nan lapenn. Apre kontantman, se kè sere.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 14, text = "Moun k'ap fè sa ki mal ap jwenn sa l'ap chache a. Konsa tou, moun k'ap fè byen an ap jwenn rekonpans li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 15, text = "Yon moun sòt ap kwè tou sa yo di l'. Men, moun ki gen konprann veye kote l'ap mete pye l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 16, text = "Moun ki gen bon konprann pran prekosyon yo, yo egzante malè. Moun sòt yo awogan, yo toujou konprann zafè yo bon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 17, text = "Lè yon moun gen san wo, l'ap toujou fè betiz. Men, moun ki kalkile anvan ap toujou rete kè pòpòz.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 18, text = "Moun san konprann aji tankou moun fou. Men, rekonpans moun ki gen lespri se konesans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 19, text = "Move moun gen pou wete chapo devan bon moun. Moun mechan gen pou bese tèt devan moun k'ap mache dwat yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 20, text = "Lè ou pòv, ou pa gen zanmi. Lè ou rich, ou plen zanmi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 21, text = "Se yon peche ou fè lè ou meprize frè parèy ou. Men, ala bon sa bon pou moun ki gen pitye pou pòv malere!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 22, text = "Lè w'ap chache fè sa ki mal, ou pèdi chemen ou. Men, lè w'ap chache fè sa ki byen, moun ap toujou renmen ou, yo p'ap janm lage ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 23, text = "Travay, w'a jwenn tou sa ou bezwen. Rete chita ap pale anpil ap rann ou pòv.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 24, text = "Rekonpans moun ki gen konprann se konesans. Moun san konprann ap toujou aji tankou moun sòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 25, text = "Lè yon temwen di laverite, li sove lavi inonsan. Lè li bay manti, li twonpe jij yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 26, text = "Lè yon moun gen krentif pou Bondye, li gen kote pou l' apiye. Pitit li yo ap jwenn pwoteksyon bò kot Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 27, text = "Gen krentif pou Bondye, w'a gen lavi. Ou p'ap tonbe lè lavi ou an danje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 28, text = "Tout pouvwa yon wa, se lè peyi l'ap kòmande a gen anpil moun. Men, lè pa gen moun nan peyi a, wa a pa vo anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 29, text = "Moun ki pa fè kòlè fasil, se moun ki gen bon konprann. Men, moun ki gen san wo fè wè jan li sòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 30, text = "Lè ou gen kè ou poze, ou kenbe kò ou an sante. Men, anvye sò lòt moun se tankou yon maladi k'ap manje ou nan zo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 31, text = "Lè w'ap peze pòv malere, se Bondye ki fè l' la w'ap derespekte. Men, lè ou aji byen ak pòv, se pi bèl sèvis ou ka rann Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 32, text = "Mechanste mechan an, se sa k'ap jete l' atè. Men, moun ki fè sa ki byen, y'ap pwoteje l' menm lè lavi l' an danje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 33, text = "Moun ki gen konprann, se tout tan y'ap chache konnen. Men, moun sòt pa chache konnen anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 34, text = "Lè gen jistis nan yon peyi, sa leve peyi a. Men, peche lenjistis se yon wont pou yon nasyon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 14, verseNumber = 35, text = "Wa a kontan lè moun k'ap travay avè l' yo fè travay yo byen. Men, l'ap move sou moun k'ap fè travay yo mal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 1, text = "Yon bon repons dous ap kalme yon moun ki ankòlè. Men, si ou reponn li rèd, w'ap fè l' pi eksite.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 2, text = "Pawòl ki soti nan bouch moun ki gen bon konprann fè ou anvi konnen tou. Men, pawòl ki soti nan bouch moun san konprann, se pawòl san sans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 3, text = "Je Seyè a toupatou, l'ap veye tout moun, bon kou mechan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 4, text = "Bon pawòl yon zanmi bay lavi. Men, move pawòl demanbre.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 5, text = "Moun fou pa koute lè papa yo ap pale yo. Men, moun ki gen bon konprann koute lè y'ap rale zòrèy yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 6, text = "Moun ki mache dwat ap toujou gen sa yo bezwen an kantite lakay yo. Men, tou sa mechan yo genyen se tèt chaje pou yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 7, text = "Lè moun ki gen bon konprann yo ap pale, se konesans y'ap bay. Men, se pa menm bagay pou moun ki san konprann yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 8, text = "Seyè a pa ka sipòte lè mechan yo ap ofri bèt pou touye pou li. Men, sa fè l' plezi anpil lè moun k'ap mache dwat yo ap lapriyè nan pye l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 9, text = "Seyè a pa ka sipòte jan mechan yo ap viv la. Men, li renmen moun k'ap fè sa ki dwat devan li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 10, text = "Moun ki fè sa ki mal mèt pare tann pinisyon yo. Men, moun ki pa ka sipòte pou yo pini yo pa lwen mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 11, text = "Seyè a konnen sa k'ap pase nan twou san fon an ak nan peyi kote mò yo ye a. Ou pa bezwen mande si l' pa konnen sa k'ap pase nan kè moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 12, text = "Moun k'ap pase moun nan betiz pa renmen moun rale zòrèy yo. Yo pa janm mande moun ki gen bon konprann konsèy.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 13, text = "Lè kè ou kontan, yo wè sa sou figi ou. Lè ou nan lapenn, ou kagou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 14, text = "Yon moun ki gen konprann toujou ap chache gen konesans. Men, moun sòt pran plezi nan pale koze san sans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 15, text = "Lè ou nan lafliksyon, chak jou se pwoblèm. Men, lè kè ou kontan, lavi se yon fèt pou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 16, text = "Pito ou pa gen anpil byen men ou gen krentif pou Bondye pase pou ou rich epi pou ou nan tèt chaje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 17, text = "Pito ou manje mayi moulen blanch ak moun ki renmen ou pase pou ou manje vyann ou byen gra ak moun ki rayi ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 18, text = "Yon moun ki gen san wo toujou ap pouse dife. Men, moun ki pa fè kòlè fasil toujou ap mete lapè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 19, text = "Lè ou parese, ou wè pwoblèm toupatou. Men, pou moun ki pa pè travay, pa gen pwoblèm ki pou rete l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 20, text = "Yon pitit byen elve fè kè papa l' kontan. Men, yon moun ki san konprann meprize manman l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 21, text = "Moun ki san konprann kontan lè y'ap aji tankou moun fou. Men, moun ki gen konprann ap toujou fè sa ki dwat.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 22, text = "Lè ou pa pran konsèy, plan travay ou p'ap mache. Lè ou pran konsèy nan men anpil moun, ou mèt sèten travay ou ap mache byen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 23, text = "Ala kontan ou kontan lè ou jwenn yon bon repons pou ou bay! Ala bon sa bon lè ou jwenn yon pawòl ki tonbe daplon!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 24, text = "Moun ki gen konprann, se yon chemen moute y'ap swiv, chemen lavi a. Yo pa pran chemen desann, chemen lanmò a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 25, text = "Seyè a ap disparèt moun awogan yo ansanm ak tout fanmi yo. Men, l'ap pwoteje kay fanm ki pèdi mari yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 26, text = "Seyè a pa ka sipòte lide mechan yo gen nan tèt yo. Men, sa fè l' plezi pou l' tande pawòl moun ki san repwòch.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 27, text = "Moun k'ap kouri dèyè lajan, se traka y'ap chache bay fanmi yo. Men, moun ki refize kite yo achte l' ap viv lontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 28, text = "Yon moun ki dwat kalkile anvan li bay repons. Men, mechan yo prese bay move pawòl.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 29, text = "Lè mechan yo ap lapriyè, Seyè a pa sou bò yo. Men, li pare zòrèy li pou l' koute sa moun ki mache dwat yo ap di l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 30, text = "Ou kontan lè ou wè moun ki kontan wè ou. Ou santi w'ap viv lè ou resevwa bon nouvèl.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 31, text = "Moun ki koute lè y'ap rale zòrèy yo pou byen yo va jwenn yon plas nan sosyete moun ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 32, text = "Moun ki refize mache sou prigad yo rayi tèt yo. Men, moun ki asepte lè yo rale zòrèy yo ap vin gen plis konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 15, verseNumber = 33, text = "Lè ou gen krentif pou Bondye, ou deja konprann anpil bagay. Lè ou soumèt devan Bondye, moun va fè lwanj ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 1, text = "Lèzòm fè lide nan kè yo. Men, dènye mo a nan men Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 2, text = "Lèzòm mete nan lide yo tou sa yo fè bon. Men, pa bliye se Bondye k'ap jije sa ki nan kè yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 3, text = "Mande Seyè a pou l' beni tout travay w'ap fè, w'ap reyisi nan tou sa w'ap fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 4, text = "Tou sa Seyè a fè, li gen yon rezon ki fè l' fè li. Menm mechan an, li kreye l' pou l' ka pini l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 5, text = "Seyè a pa ka sipòte moun k'ap gonfle lestonmak yo sou moun. Wè pa wè, l'ap fè yo peye sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 6, text = "Si ou pa janm vire do bay Bondye, si ou toujou kenbe pawòl ou, Bondye va padonnen peche ou yo. Lè yon moun gen krentif pou Bondye, l'ap evite fè sa ki mal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 7, text = "Lè yon moun ap viv yon jan ki fè Seyè a plezi, Seyè a ap fè ata lènmi l' yo aji byen avè l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 8, text = "Pito ou fè ti pwofi nan fè sa ki dwat pase pou ou fè gwo benefis nan fè sa ki mal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 16, verseNumber = 9, text = "Lèzòm fè plan travay yo nan kè yo. Men, se Seyè a k'ap dirije sa y'ap fè a.", bookId = 20),
