        Verse(book = "Pwovèb", chapter = 20, verseNumber = 9, text = "Ki moun ki ka di: mwen lave konsyans mwen, mwen wete tout peche ki te sou li?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 10, text = "Seyè a pa ka sipòte moun k'ap sèvi ak de pwa de mezi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 11, text = "Yon timoun moutre ou sa l'ap soti nan sa l'ap fè. Ou ka di si l'ap serye, si l'ap bon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 12, text = "Se Seyè a ki ban nou je pou nou ka wè, se li menm ki ban nou zòrèy pou nou ka tande.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 13, text = "Pa renmen dòmi twòp pou ou pa vin pòv. Souke kò ou. W'a jwenn kont manje pou ou manje.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 14, text = "Lè moun ap machande, machandiz pa janm bon. Fini yo fin achte, y'ap mache di jan yo fè yon bon zafè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 15, text = "Lè yon moun ki gen konprann ap pale sa gen plis valè pase kantite lò ak pyè ki koute chè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 16, text = "Si yon moun sòt jouk pou li asepte bay pawòl li pou dèt yon etranje, se pou yo pran ata rad ki sou li jouk lòt la peye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 17, text = "Lajan ou fè nan move kondisyon ka dous lè ou fèk genyen l'. Men, apre sa, se tankou ti wòch anba dan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 18, text = "Pran konsèy, tou sa ou gen lide fè ap mache byen. Pa kouri fè lagè san ou pa konnen sa w'ap fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 19, text = "Bouch alèlè pa kenbe sekrè. Pa mele ak moun ki pale twòp.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 20, text = "Moun ki bay manman l' ak papa l' madichon p'ap viv lontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 21, text = "Richès ou ranmase fasil fasil p'ap janm vin yon benediksyon pou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 22, text = "Pa janm di se ou ki pou vanje tèt ou. Mete konfyans ou nan Seyè a, l'a delivre ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 23, text = "Seyè a pa ka sipòte moun k'ap sèvi ak de pwa de mezi. Sa pa bon pou ou sèvi ak move balans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 24, text = "Se Seyè a ki louvri chemen devan nou. Ki jan lèzòm ka rive konprann lavi?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 25, text = "Pa prese fè Bondye pwomès. Ou ka règrèt sa pita.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 26, text = "Yon wa ki gen bon konprann ap rive dekouvri tout mechan yo. L'ap san pitye lè l'ap pini yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 27, text = "Se Seyè a ki ban nou konsyans nou. Se tankou yon lanp k'ap klere pou fè nou wè tou sa n'ap fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 28, text = "Yon wa ap rete wa si li se nèg serye, si li toujou kenbe pawòl li. L'ap toujou wa si li pa nan patipri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 29, text = "Se kouraj ki fè valè yon jenn gason. Men, pou granmoun, se cheve blan l' yo ki fè valè l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 20, verseNumber = 30, text = "Move esperyans ka fè nou chanje. Malè ka fè nou vin gen bon santiman.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 1, text = "Seyè a dirije lespri yon wa, menm jan li dirije yon kouran dlo nan kannal. Li mennen l' kote li vle.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 2, text = "Lèzòm mete nan lide yo tou sa y'ap fè dwat. Men, pa bliye, se Seyè a k'ap jije sa ki nan kè yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 3, text = "Fè sa ki dwat. Pa nan patipri. Sa fè Seyè a plezi pi plis pase bèt ou ta touye pou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 4, text = "Fè awogans, gonfle lestonmak yo sou moun, se sa ase mechan yo ap chache fè. Tou sa se peche.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 5, text = "Lè ou pran san ou pou ou travay, tou sa w'ap fè ap ba ou benefis. Men, lè ou twò prese, ou p'ap janm gen anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 6, text = "Moun k'ap mache bay manti pou fè lajan ap kouri dèyè van. Se lanmò y'ap chache.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 7, text = "Move zak mechan yo ap fè a ap fini ak yo, paske yo derefize fè sa ki dwat devan Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 8, text = "Moun k'ap fè sa ki mal ap mache sou chemen plen detou. Men, inonsan yo fè sa ki dwat.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 9, text = "Pito ou rete pou kont ou nan yon kwen galata pase pou ou rete nan kay ak yon fanm ki toujou ap chache kont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 10, text = "Mechan toujou anvi fè sa ki mal. Yo pa gen pitye pou pesonn.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 11, text = "Lè yo pini yon moun ki renmen pase lòt nan betiz, se yon leson pou moun ki pa gen lespri. Men, moun ki gen bon konprann, lè yo pale avè l', li vin gen plis konesans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 12, text = "Bondye pa nan patipri, li konnen sa k'ap pase anndan kay mechan yo. Li fè malè tonbe sou yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 13, text = "Si ou fèmen zòrèy ou pou ou pa tande pòv k'ap mande ou lacharite, konsa tou pesonn p'ap tande ou lè w'a mande sekou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 14, text = "Lè yon moun fache sou ou, si ou ba li yon kado an kachèt, w'a fè l' vin frèt. Wi, yon kado glise nan pòch li ap kase fe l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 15, text = "Lè yo rann jistis san patipri, moun ki mache dwat yo gen kè kontan. Men, mechan yo gen kè kase.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 16, text = "Lè yon moun pèdi chemen l' pou l' aji tankou moun fou, se lanmò k'ap fè li siyon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 17, text = "Lè ou renmen plezi, w'ap toujou pòv. Lè ou renmen bon bweson ak bon manje, ou p'ap janm gen lajan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 18, text = "Lè pou malè ta tonbe sou moun ki mache dwat yo, se sou mechan yo li tonbe.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 19, text = "Pito ou viv pou kont ou nan yon dezè pase pou ou viv nan kay ak yon fanm ki tout tan ap chache kont, ki tout tan ap plenyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 20, text = "Moun ki gen konprann ap gen gwo richès ak kantite bon manje lakay yo. Men, moun sòt gaspiye tout lajan yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 21, text = "Lè yon moun pa fè lenjistis, lè li gen bon kè, l'ap viv lontan. Tout zafè l' ap mache byen, y'ap respekte l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 22, text = "Yon nonm lespri ka pran yon lavil kote ki gen anpil grannèg. L'ap kraze fòs ki t'ap fè yo pa pè anyen an.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 23, text = "Veye bouch ou ak lang ou, ou p'ap nan pwoblèm.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 24, text = "Moun k'ap pase Bondye nan betiz, se moun ki radi, se moun ki awogan. Yo pa gen konsiderasyon pou pesonn.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 25, text = "Parese pa anvi leve ni lou ni lejè. Se sa k'ap touye l' la tou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 26, text = "Tout lajounen l'ap kalkile sou sa l' ta renmen genyen. Men, moun ki mache dwat yo gen pou bay, y'ap bay san gad dèyè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 27, text = "Seyè a pa ka sipòte lè mechan yo ap ofri bèt pou touye pou li. Sa pi mal toujou lè yo ofri bèt pou touye ba li avèk lide mechanste dèyè tèt yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 28, text = "Temwen k'ap bay manti gen pou l' mouri. Men, yo p'ap koupe pawòl nan bouch moun ki peze sa l'ap di.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 29, text = "Mechan toujou pran pòz radi l'. Men, moun ki mache dwat la konnen sa l'ap fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 30, text = "Devan Seyè a pa gen ni moun konnen, ni moun lespri, ni moun ki gen bon konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 21, verseNumber = 31, text = "Moun pare chwal pou y' al fè lagè, men se Seyè a k'ap deside kilès k'ap genyen batay la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 1, text = "Pito yo nonmen non ou an byen pase pou ou gen anpil richès. Pito moun gen anpil konsiderasyon pou ou pase pou ou gen anpil lajan ak anpil lò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 2, text = "Pa gen diferans ant moun rich ak moun pòv, paske tou de se kreyati Bondye yo ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 3, text = "Moun ki gen konprann, lè li wè malè ap vin sou li, li wete kò l'. Men, moun sòt pote lestonmak li bay, epi se li ki peye sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 4, text = "Soumèt ou devan Bondye, gen krentif pou li: W'a gen richès, y'a nonmen non ou, w'a viv lontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 5, text = "Moun ki mache kwochi jwenn pikan ak pèlen sou wout yo. Si ou renmen lavi, pa fè menm wout ak yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 6, text = "Bay yon timoun prensip li dwe swiv. Jouk li mouri, li p'ap janm bliye l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 7, text = "Moun rich ap donminen sou moun pòv. Lè ou prete lajan nan men yon moun, ou tounen timoun devan pòt li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 8, text = "Lè ou simen lenjistis, ou rekòlte malè. Ou rete konsa sak te fè ou gen gwo kòlèt la disparèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 9, text = "Bondye beni moun ki gen bon kè, paske lè moun ki gen bon kè wè yon pòv, yo separe sa yo genyen an avè l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 10, text = "Mete moun k'ap pase lòt moun nan betiz la deyò, lamenm tout kont, tout joure ap sispann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 11, text = "Moun ki pa gen move lide dèyè tèt yo epi ki gen bon pawòl nan bouch yo ap gen wa a pou zanmi yo. Men, Bondye renmen moun ki sensè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 12, text = "Seyè a pwoteje moun k'ap di verite. Men, li fè moun k'ap bay manti yo wont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 13, text = "Parese rete chita lakay li, li di si li soti bèt nan bwa va manje l' nan lari a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 14, text = "Pawòl fanm adiltè se gwo pèlen. Lè Seyè a move sou yon moun, moun lan ap pran nan pèlen sa a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 15, text = "Timoun toujou ap fè move bagay. Men, fwèt ap fè yo pa rekonmanse ankò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 16, text = "Lè w'ap peze yon pòv malere se lespri l' w'ap louvri. Lè w'ap fè moun rich kado, se pòv w'ap fè l' pòv.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 17, text = "Louvri zòrèy ou, koute pawòl moun ki gen bon konprann yo. Chache konprann sa m'ap moutre ou la a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 18, text = "L'a bon pou ou toujou kenbe yo nan kè ou, pou yo ka toujou anba lang ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 19, text = "Koulye a, mwen pral moutre ou tout pawòl sa yo, ou menm tou, pou ou ka mete konfyans ou nan Seyè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 20, text = "Depi lontan, mwen te ekri bon pawòl sa yo pou ou. W'a jwenn anpil bon konsèy ak konesans ladan yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 21, text = "Y'a fè ou konnen verite a jan li ye a. Konsa, w'a pote bon repons bay moun ki te voye ou la. Men yo:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 22, text = "Pa pran ti sa pòv la genyen an paske se pòv li ye. Pa pwofite sou ti malere yo nan tribinal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 23, text = "Se Seyè a ki va plede kòz yo pou yo. L'a touye moun ki vòlò malere sa yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 24, text = "Pa fè zanmi ak moun ki ankòlè fasil. Pa mache ak moun ki gen san wo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 25, text = "W'a pran move mès yo. W'a rale malè sou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 26, text = "Pa pwomèt pou ou reskonsab dèt yon lòt moun fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 27, text = "Si ou pa ka peye, y'a sezi ata kabann anba do ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 28, text = "Pa janm deplase bòn tè kote granmoun lontan te mete yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 22, verseNumber = 29, text = "Moutre m' yon nonm ki gen ladrès nan sa l'ap fè. Se moun konsa k'ap rive travay ak chèf. Li pa pral travay ak moun ki pa anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 1, text = "Lè chèf envite ou manje sou menm tab ak li, pa janm bliye ki moun li ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 2, text = "Si ou se yon moun ki gen bon lapeti, kontwole bouch ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 3, text = "Pa pote lanvi sou bon ti manje l'ap ofri ou yo. Se ka yon pèlen li tann pou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 4, text = "Pa touye tèt ou ap kouri dèyè lajan pou ou vin rich. Wete lide ou sou sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 5, text = "Paske, anvan ou bat je ou, li gen tan disparèt. Ou ta di lajan gen zèl. Li rete konsa, li vole, li ale.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 6, text = "Pa chita pou ou manje sou menm tab ak moun ki tikoulout. Pa pote lanvi sou manje l'ap ofri ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 7, text = "Li chich ata ak tèt pa li, ale wè avè ou. L'ap di ou: Manje non, monchè! Bwè non! Men se pa ak tout kè li l'ap di ou sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 8, text = "W'a vonmi tou sa ou te manje a. Tout bèl pawòl ou te di l' yo p'ap sèvi ou anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 9, text = "Pa chache fè yon moun san konprann konprann anyen. Li p'ap tande anyen nan sa w'ap di l' la. Lèfini, l'ap meprize ou met sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 10, text = "Pa janm deplase bòn tè kote yo te ye depi lontan an. Pa antre sou jaden ki pou timoun san papa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 11, text = "Se Bondye k'ap defann yo, li gen anpil pouvwa. L'a plede kòz yo kont ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 12, text = "Mete tèt ou an plas lè y'ap moutre ou kichòy. Louvri zòrèy ou lè yon moun ki gen konesans ap pale.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 13, text = "Ou pa bezwen pè bat yon timoun. Yon bèl kal, sa p'ap touye l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 14, text = "Okontrè, si ou bat li, w'a sove nanm li pou l' pa mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 15, text = "Pitit mwen, si ou gen bon konprann, mwen p'ap manke kontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 16, text = "M'a kontan anpil lè m'a tande bon pawòl k'ap soti nan bouch ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 17, text = "Pa pote lanvi sou moun k'ap fè sa ki mal. Nan tou sa w'ap fè, toujou gen krentif pou Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 18, text = "Paske gen denmen. Se pa pou gremesi w'ap tann sa w'ap tann lan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 19, text = "Louvri zòrèy ou, gason mwen, pou ou ka gen bon konprann, pou ou ka mache dwat. Kalkile byen kote w'ap mete pye ou, pou ou ka mache dwat.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 20, text = "Pa fè zanmi avèk moun k'ap bwè twòp, ak moun k'ap fè safte.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 21, text = "Paske moun k'ap fè metye bwè ak moun ki afre ap vin pòv. Si ou pase tout tan ou ap dòmi, talè konsa w'ap mache yon men devan yon men dèyè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 22, text = "Pitit mwen, koute papa ou ki fè ou. Pa meprize manman ou lè li fin granmoun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 23, text = "Verite, konesans, lespri ak bon konprann, se bagay ou mèt peye chè pou ou genyen. Men, pa janm vann sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 24, text = "Papa ki gen yon pitit k'ap mache dwat ap toujou kontan. Manman ki fè yon pitit ki gen bon konprann ap toujou gen kè kontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 25, text = "Fè kè papa ou ak manman ou kontan. Fè kè manman ki fè ou la kontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 26, text = "Pitit mwen, louvri zòrèy ou pou tande sa m'ap di ou. Louvri je ou byen pou ou wè jan m'ap viv.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 27, text = "Fanm jennès se tankou yon twou pèlen, fanm adiltè se tankou yon pi jis jis.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 28, text = "Tankou vòlò, y'ap pare pèlen pou ou. Yo fè anpil gason pèdi tèt yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 29, text = "Ki moun ki nan tèt chaje, ki nan lapenn? Ki moun ki toujou nan kont, ki tou tan ap plenyen? Ki moun k'ap pran kou san rezon, ki gen je yo tou wouj?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 30, text = "Se moun k'ap bwè twòp gwòg, moun k'ap kouri dèyè tranpe.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 31, text = "Pa kite bweson pran nanm ou, ou te mèt wè jan li bèl, jan li klè nan vè a. Lè ou bwè l', li desann dous nan gòj ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 32, text = "Men, pita ou santi se tankou yon move sèpan ki mòde ou, yon sèpan aspik ki pike ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 33, text = "W'ap wè tout bagay ap vire devan je ou, w'ap depale.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 34, text = "W'ap santi tankou si ou te sou lanmè: w'ap tankou si ou te sou tèt yon ma batiman.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 23, verseNumber = 35, text = "Lè sa a w'a di: Gen lè yo bat mwen, mwen pa santi sa. Gen lè yo te ban m' kou, mwen pa konn sa. Kilè m'a leve la a? Mwen ta pran yon ti kou ankò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 1, text = "Pa anvye sò mechan yo. Pa chache fè zanmi ak yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 2, text = "Yon sèl bagay ki nan tèt yo, se fè mechanste. Yon sèl pawòl ki nan bouch yo, se fè moun mal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 3, text = "Bon konprann ap fè kay ou kanpe. Bon konesans ap fè l' kanpe fèm.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 4, text = "Kote ki gen konesans, pyès kay yo plen ak bon bagay ki koute chè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 5, text = "Pito ou gen bon konprann pase ou gen fòs. Wi, moun ki gen konesans vo plis pase moun ki gwonèg.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 6, text = "Paske, se pou ou ranje plan ou anvan ou antre nan batay. Plis ou gen moun k'ap ba ou konsèy, plis ou gen chans pou ou genyen batay la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 7, text = "Pawòl moun konprann twò wo pou moun san konprann. Yo pa gen anyen pou yo di kote koze serye ap pale.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 8, text = "Lè yon moun tout tan ap kalkile jan pou l' fè sa ki mal, y'ap rele l' malveyan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 9, text = "Tou sa moun san konprann gen lide fè, se fè sa ki mal. Konsa tou, moun pa vle wè moun k'ap plede pase moun nan betiz.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 10, text = "Si jou malè ou pa gen kouraj pou kenbe, ou pa t' janm gen fòs vre.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 11, text = "Delivre moun y'ap trennen pou y' al touye. Sove moun y'ap bourade pou y' al egzekite.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 12, text = "Si ou pran pòz ou pa t' konn sa, chonje Bondye. Li menm k'ap jije sa ki nan kè moun, l'ap wè sa. Li menm k'ap veye tou sa w'ap fè, l'ap konn sa. L'ap fè tout moun peye pou sa yo fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 13, text = "Pitit mwen, bwè siwo myèl, sa bon pou ou. Menm jan siwo myèl k'ap koule soti nan gato myèl dous nan bouch ou,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 14, text = "se konsa konesans ak bon konprann bon pou nanm ou. Si ou genyen yo, w'a fè chemen ou nan lavi. Sa w'ap tann lan, lavalas p'ap pote l' ale.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 15, text = "Pa janm fè plan tankou mechan yo pou chache fofile kò ou anndan kay moun k'ap mache dwat. Pa chache devalize kote l' rete a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 16, text = "Paske, moun k'ap mache dwat yo te mèt tonbe sèt fwa. Pa pè, y'ap toujou leve ankò. Men, nan mechanste yo, mechan yo ap tonbe, yo p'ap ka leve ankò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 17, text = "Pa prese fè kè ou kontan lè malè rive lènmi ou. Pa kouri fè fèt lè li bite.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 18, text = "Seyè a ap wè sa. Sa p'ap fè l' plezi. Li ka rive pa pini l' poutèt sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 19, text = "Pa kite moun k'ap fè sa ki mal fè ou pèdi tèt ou. Pa anvye sò mechan yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 20, text = "Paske mechan yo pa pral lwen. Lavi yo tankou yon lanp k'ap mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 21, text = "Pitit mwen, gen krentif pou Seyè a. Respekte wa a. Ou pa gen anyen pou ou wè ak moun k'ap kenbe tèt ak yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 22, text = "Moun sa yo ap rete konsa, malè ap tonbe sou yo. Ou pa janm konnen ki kalite malè Seyè a osinon wa a ka fè rive sou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 23, text = "Men lòt pawòl moun ki gen bon konprann yo te di ankò. Sa pa bon pou yon jij gade sou figi moun lè l'ap rann jijman.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 24, text = "Lè yon jij di yon moun ki fè sa ki mal: Se ou ki gen rezon, jij sa a, tout moun gen pou madichonnen l'. Y'ap rayi l' toupatou sou latè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 25, text = "Men, jij ki pini moun ki antò a va gen kè kontan. Bondye va beni l'. Tout zafè l' va mache byen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 26, text = "Lè ou bay yon bon repons, ou aji tankou yon bon zanmi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 27, text = "Regle tout zafè ou. Mete jaden ou anfòm. Apre sa, ou mèt tabli.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 28, text = "Pa leve pale sou do frè parèy ou san rezon. Pa bay manti sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 29, text = "Pa janm di li fè m', m'ap fè l' tou. M'ap fè l' peye sa li fè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 30, text = "Mwen pase bò jaden yon nonm parese, bò jaden rezen yon moun ki san konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 31, text = "Pikan te fin pran jaden an nèt. Move zèb t'ap pouse toupatou. Lantouraj jaden yo te fin tonbe.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 32, text = "Lè mwen wè sa, mwen kalkile. Mwen gade, sa ban m' yon leson.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 33, text = "Dòmi, kabicha, kouche sou do, kwaze men ou dèyè tèt ou... Se bon!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 24, verseNumber = 34, text = "W'ap rete konsa, w'ap wè ou pòv. Mizè ap tonbe sou ou tankou yon ansasen san ou pa atann.", bookId = 20)
    )

    private fun part4(): List<Verse> = listOf(
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 1, text = "Men kèk lòt pwovèb wa Salomon. Se moun nan palè Ezekyas, wa peyi Jida a, ki te kouche yo sou papye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 2, text = "Bondye konnen lè pou l' kite nou konprann, se sa ki fè pouvwa li. Wa yo toujou ap chache konprann, se sa ki fè moun respekte yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 3, text = "Menm jan ou pa konnen wotè syèl la ak fondè tè a, se konsa tou ou pa ka konnen sa k'ap pase nan tèt yon wa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 4, text = "Wete tout vye kras ki nan ajan an. Efèv la ap ba ou yon bèl travay byen fèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 5, text = "Wete tout mechan bò kote wa a, gouvènman l' lan ap chita byen chita. p'ap gen lenjistis.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 6, text = "Pa fè grandizè devan wa a. Pa chita nan plas grannèg yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 7, text = "Pito yo di ou moute pi wo, pase pou yo fè ou bay plas la, pou ou ta wont devan chèf la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 8, text = "Sa ou wè ak je ou, pa prese al rapòte l' lajistis. Si apre sa, yon lòt temwen kanpe pou demanti ou, lè sa a kisa ou va fè?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 9, text = "Lè ou gen kont ak yon moun, regle zafè nou san nou pa mete lòt moun ladan li. Pa mete sekrè l' deyò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 10, text = "Paske, lè moun konnen ou pa ka kenbe sekrè, y'a fè ou wont. Y'a ba ou move non.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 11, text = "Lè ou bay bon pawòl ki tonbe daplon se tankou yon moso lò byen travay yo plake sou yon moso ajan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 12, text = "Lè yon moun ki gen bon konprann rale zòrèy moun ki gen tande, se tankou zanno ak kolye ki fèt ak bon lò ou mete sou ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 13, text = "Yon komisyonè ki p'ap twonpe moun ki voye l' la, se tankou yon bon vè dlo byen fre w'ap bwè nan mitan chalè rekòt. L'ap remoute kouraj mèt li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 14, text = "Moun ki toujou ap pwomèt san yo pa janm kenbe pwomès yo, se tankou nwaj ak van ki pa janm pote lapli.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 15, text = "Lè ou pa fè kòlè fasil, ou jwenn jwen pou fè chèf la kwè sa ou vle. Konsa tou, ak pawòl dous, w'ap kraze tout antrav ou ta ka jwenn sou chemen ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 16, text = "Lè ou jwenn siwo myèl, bwè kantite ou ka bwè. Si ou pran twòp, l'a fè kè ou plen, l'a fè ou vonmi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 17, text = "Konsa tou, pa al rann vizit twò dri lakay zanmi ou, pou li pa bouke avè ou, pou l' pa rayi ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 18, text = "Yon moun k'ap mache bay manti sou moun, se tankou yon makak chaplèt, yon nepe, yon flèch byen pwenti. Li ka touye ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 19, text = "Jou malè, si ou mete konfyans ou sou moun trèt, se tankou si ou vle mòde ak dan pouri, osinon kouri sou pye foule.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 20, text = "Chante mereng pou yon moun ki nan lapenn, se tankou moun ki wete tout rad sou li nan fredi, se tankou si ou prije sitwon sou yon malenng.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 21, text = "Si lènmi ou grangou, ba li manje. Si li swaf dlo, ba li dlo pou l' bwè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 22, text = "Lè sa a, w'a fè l' wont anpil. Seyè a va rekonpanse ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 23, text = "Tripotaj fè moun fè kòlè, menm jan nòde bay lapli.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 24, text = "Pito ou viv pou kont ou nan yon kwen galata pase pou w'ap viv nan yon kay ansanm ak yon fanm k'ap chache kont tout tan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 25, text = "Lè ou resevwa yon bon nouvèl ki soti nan peyi Jida, se tankou yon vè dlo fre pou yon moun ki sot moute mòn.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 26, text = "Lè yon moun ki mache dwat kite yon mechan pran tèt li, se tankou yon sous dlo moun mache ladan l', se tankou yon pi yo sal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 27, text = "Twòp siwo myèl pa bon pou lasante. Konsa tou, pa chache pou moun nonmen non ou twòp.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 25, verseNumber = 28, text = "Si ou pa kapab kontwole kòlè ou, ou tankou yon lavil san ranpa. Y'ap anvayi l' fasil. Y'ap mete men sou ou fasil.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 1, text = "Menm jan moun pa bezwen tann pou fè gwo fredi nan sezon chalè, ni pou lapli tonbe nan sezon rekòt, konsa tou, moun san konprann pa bezwen tann pou yo fè lwanj li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 2, text = "Madichon pa ka fè ou anyen si ou pa antò. Se tankou ti zwezo k'ap vòltije sou branch bwa, ziwondèl k'ap vole nan syèl la yo ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 3, text = "Fwèt pou chwal, baboukèt pou bourik, baton pou do moun ki san konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 4, text = "Pa reponn moun sòt yo menm jan yo pale a, pou ou pa parèt sòt menm jan ak yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 5, text = "Reponn moun sòt yo dapre jan yo pale a, w'a fè yo wè se moun sòt yo ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 6, text = "Yon moun ki voye yon moun sòt fè komisyon, se tankou si li te koupe janm li. Se traka l'ap chache bay tèt li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 7, text = "Yon moun ki san konprann sèvi ak yon pwovèb menm jan yon moun bwete sèvi ak move janm lan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 8, text = "Fè lwanj yon moun ki san konprann, se tankou si ou te mare wòch la anvan ou tire fistibal la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 9, text = "Yon moun san konprann k'ap bay yon pwovèb, se tankou yon moun sou k'ap chache wete yon pikan nan dwèt li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 10, text = "Patwon ki pran nenpòt moun san konprann osinon nenpòt moun k'ap pase nan lari pou travay pou li, se yon danje pou tout moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 11, text = "Menm jan yon chen tounen vin manje sa li vonmi, se konsa moun san konprann yo ap toujou fè sa y'ap fè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 12, text = "Gen plis espwa pou yon moun ki san konprann pase pou yon moun ki mete nan tèt li li konprann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 13, text = "Parese a di: Gen bèt nan bwa sou wout la. Gen yon lyon nan lari a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 14, text = "Parese a ap vire adwat agoch nan kabann li, menm jan yon pòt ap vire louvri fèmen sou gon li yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 15, text = "Parese a pran kiyè l' nan men l'. Men, pou l' leve l' mete nan bouch li, se yon pakèt afè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 16, text = "Parese mete nan tèt li li gen plis konprann pase sèt moun lespri ki konn sa y'ap di.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 17, text = "Moun k'ap foure bouch nan koze ki pa gade l', se tankou moun k'ap rale ke chen li jwenn sou gran chemen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 18, text = "-(we vèsè pwochen)", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 19, text = "Moun k'ap mache twonpe moun, apre sa pou li di: Aa monchè! Se jwe mwen t'ap jwe, moun konsa tankou moun fou k'ap voye bwa dife ak wòch pou touye moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 20, text = "Kote ki pa gen bwa, pa gen dife. Kote ki pa gen tripòt, pa gen kont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 21, text = "Chabon kenbe recho a limen. Bwa pa kite dife a mouri. Konsa tou, moun ki renmen chache kont toujou ap pouse dife.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 22, text = "Tripotay dous nan zòrèy moun ki vle tande yo. Sa mache nan san yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 23, text = "Yon moun ki gen bèl pawòl nan bouch li men ki gen move kè, se tankou bèl penti sou bwa pouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 24, text = "Ipokrit ki rayi moun toujou ap bay bèl pawòl. Men, nan kè l', se twonpe l'ap twonpe moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 25, text = "Lè l'ap pale konsa, ou pa bezwen kwè l', paske nan fon kè l', se mechanste ase ki genyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 26, text = "Li te mèt kache sa, tout moun gen pou wè mechanste l'ap fè yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 27, text = "Moun k'ap tann pèlen pou lòt se yo menm k'ap pran ladan li. Moun ki konmanse woule wòch la, se li menm ankò wòch la ap kraze.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 26, verseNumber = 28, text = "Fòk ou rayi yon moun vre pou fè manti sou li. Lè w'ap flate moun, se tèt ou w'ap fè tò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 1, text = "Pa fè grandizè pou sa ou pral fè denmen. Ou wè jòdi, ou pa konn denmen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 2, text = "Kite lòt moun pale byen pou ou. Pa fè sa ou menm. Kite etranje fè lwanj pou ou. Pa janm fè lwanj tèt pa ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 3, text = "Wòch lou, sab lou. Men, yo pa ka pi lou pase yon moun san konprann lè l' fache.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 4, text = "Lè yon moun ankòlè, li kraze brize. Men, ki moun ki ka kenbe tèt ak yon moun k'ap fè jalouzi?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 5, text = "Pito ou rale zòrèy yon moun kareman pase pou ou kite l' konprann sa li fè a pa anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 6, text = "Lè yon zanmi ap rale zòrèy ou, se byen ou li vle wè. Men, lè yon lènmi ap pase men l' nan kou ou, se twonpe l'ap twonpe ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 7, text = "Lè vant moun plen, yo refize ata siwo myèl. Lè moun grangou vre, menm bagay anmè gou nan bouch.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 8, text = "Yon moun ki lwen lakay li, se tankou yon zwezo ki byen lwen nich li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 9, text = "Losyon ak lwil santi bon bay kè kontan. Konsèy yon bon zanmi remoute kouraj.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 10, text = "Pa janm bliye zanmi ou, ni zanmi papa ou. Lè zafè ou pa bon, pa al lakay frè ou. Yon bon vwazen pi bon pase yon frè ki lwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 11, text = "Pitit mwen, aprann gen bon konprann. Fè kè m' kontan. Konsa, m'a ka reponn moun k'ap kritike m' yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 12, text = "Moun ki gen konprann, lè li wè malè ap vin sou li, li wete kò l'. Moun sòt pote lestonmak li bay, epi se li ki peye sa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 13, text = "Si yon moun sòt jouk pou li asepte bay pawòl li pou dèt yon etranje, se pou yo sezi ata rad ki sou li jouk lòt la peye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 14, text = "Si ou di yon zanmi ou bonjou twò fò granmaten, se tankou si ou te ba li madichon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 15, text = "Yon fanm ki toujou ap chache kont, se tankou yon goutyè k'ap degoute lè lapli ap tonbe tout lajounen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 16, text = "Si ou rive fè l' pe bouch li, w'a kenbe van ak men ou, w'a kenbe lwil ak dwèt ou tou!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 17, text = "Menm jan fè file fè, konsa tou pou moun, yonn aprann nan men lòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 18, text = "Moun ki pran swen yon pye rezen, se li ki va jwenn rezen pou li manje. Moun ki fè travay mèt li byen, y'a gen respè pou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 19, text = "Lè ou gade nan glas, se pwòp figi ou ou wè ladan l'. Konsa tou, lè ou gade nan kè yon moun, ou wè ki moun li ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 20, text = "Menm jan toujou gen plas pou mò kote mò yo ye a, konsa tou, toujou gen plas pou lanvi nan kè moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 21, text = "Yo pase lò ak ajan nan dife pou wè si yo bon. Konsa tou, dapre jan yo nonmen non yon moun, yo ka di ki moun li ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 22, text = "Ou te mèt woule yon moun sòt anba baton tankou yo bat pwa, se pa sa k'ap fè l' kite sòt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 23, text = "Chache konnen jan tout bèt ou yo ye. Pran swen yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 24, text = "Richès pa la pou tout tan. Ou ka pa rive pase tout byen ou bay pitit pitit ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 25, text = "Lè ou koupe zèb, li pouse ankò. Konsa, toujou gen zèb sou mòn yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 26, text = "Mouton ou yo ap ba ou lenn pou fè rad met sou ou. Bouk kabrit yo ap rapòte ou lajan pou achte tè pou fè jaden.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 27, verseNumber = 27, text = "W'a jwenn kont lèt kabrit pou ou bwè ak fanmi ou ansanm ak moun k'ap sèvi lakay ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 1, text = "Mechan yo pa bezwen moun dèyè yo pou yo kouri. Men, moun ki mache dwat yo brav tankou lyon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 2, text = "Lè nan yon peyi moun ap fè sa ki mal, chak jou gen yon lòt chèf. Men avèk yon moun ki gen konprann, ki konnen sa l'ap fè, gouvènman an ap kanpe pou lontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 3, text = "Yon pòv k'ap peze pi pòv pase l', se tankou yon gwo lapli ki gate tout jaden nèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 4, text = "Moun ki pa respekte lalwa bay mechan yo pye sou moun. Men, moun ki fè sa lalwa mande, se moun ki pran pozisyon kont mechan yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 5, text = "Mechan yo pa konnen sa ki rele jistis. Men, moun k'ap sèvi Seyè a konprann tout bagay.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 6, text = "Pito ou pòv men ou serye, pase pou ou rich men ou vòlè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 7, text = "Yon jenn gason ki fè tou sa lalwa mande, se pitit ki gen lespri. Men, moun ki fè zanmi ak vakabon se yon wont pou papa l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 8, text = "Moun ki vin rich nan prete moun lajan, nan bay kout ponya, se anpile y'ap anpile lajan pou moun ki konn pran ka malere.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 9, text = "Lè ou refize fè sa lalwa mande ou fè a, ata lapriyè w'ap fè a p'ap fè Bondye plezi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 10, text = "Lè yon moun chache pran tèt yon nonm serye pou fè l' fè sa ki mal, se li menm k'ap pran nan pèlen an. Men moun serye a va jwenn bon rekonpans.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 11, text = "Yon nonm rich mete nan tèt li li gen bon konprann. Men, yon pòv ki gen lespri ap dekouvri l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 12, text = "Lè se moun k'ap fè sa ki dwat ki rive chèf, se fèt pou tout moun. Men, lè se mechan an ki rive chèf, tout moun al kache.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 13, text = "Moun k'ap kache peche p'ap janm wè zafè yo mache. Men, Bondye va gen pitye pou moun ki rekonèt peche yo, pou moun ki chanje lavi yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 14, text = "Ala bon sa bon pou moun ki toujou gen krentif pou Bondye! Men, moun k'ap fè tèt di ak Bondye ap wè malè tonbe sou yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 15, text = "Yon chèf malveyan se tankou lyon ki move, tankou lous ki grangou. Pòv malere san sekou devan yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 16, text = "Lè yon chèf pa gen konprann, l'ap peze moun, l'ap fè mechanste. Men, moun ki pa vle wè moun k'ap vòlò ap gouvènen lontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 17, text = "Lè yon moun touye yon lòt, konsyans li boulvèse l', l'ap kouri chache lanmò. Piga pesonn chache kenbe l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 18, text = "Malè p'ap rive moun k'ap mennen yon lavi san repwòch. Men, moun ki pa serye, k'ap mache pye gaye, y'ap rete konsa, y'ap tonbe.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 19, text = "Yon moun ki travay di nan jaden l' ap jwenn kont manje pou l' manje. Men, moun k'ap fè bagay ki p'ap sèvi anyen ap toujou pòv.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 20, text = "Yon nonm ki serye nan sa l'ap fè ap jwenn anpil benediksyon. Men, yo p'ap manke pini moun k'ap prese pou l' rich.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 21, text = "Sa pa bon pou gade moun sou figi. Men, pou nenpòt ti kraze kòb, yon jij ka fè betiz.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 22, text = "Moun ki anvi tout toujou ap prese pou yo rich. Yo pa wè grangou k'ap tann yo pi devan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 23, text = "Lè ou rale zòrèy yon moun, pita l'ap gen plis konsiderasyon pou ou pase pou moun k'ap achte figi l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 24, text = "Moun k'ap vòlò papa l' ak manman l', epi k'ap di nan kè l': Se pa anyen sa, li menmman parèyman ak moun k'ap mache brize.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 25, text = "Moun ki anvi tout pou yo ap toujou nan kont. Men, moun ki mete konfyans yo nan Seyè a p'ap janm manke anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 26, text = "Moun ki gen konfyans nan pwòp tèt yo, se moun fou yo ye. Men, moun ki fè sa li konnen li dwe fè a ap sove.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 27, text = "Moun ki bay pòv p'ap janm manke anyen. Men, moun ki fè tankou li pa wè pòv yo chaje ak madichon.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 28, verseNumber = 28, text = "Lè se mechan ki rive chèf, tout moun al kache. Men, tonbe mechan yo tonbe, moun k'ap mache dwat yo kanpe ankò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 1, text = "Moun k'ap fè tèt di lè y'ap rale zòrèy yo, se moun k'ap rete konsa y'ap tonbe san yo pa ka leve ankò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 2, text = "Lè se moun serye ki chèf, pèp la kontan. Men, lè se yon mechan k'ap gouvènen, pèp la nan lapenn.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 3, text = "W'ap fè kè papa ou kontan si ou toujou ap chache bon konprann. Moun k'ap frekante jennès, se lajan l' l'ap gaspiye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 4, text = "Lè yon wa pa nan patipri, peyi a kanpe byen fèm. Men, depi yon chèf nan resevwa lajan sou kote, se fini l'ap fini ak peyi a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 5, text = "Moun k'ap flate moun, se yon pèlen y'ap pare sou wout yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 6, text = "Moun mechan pran nan mechanste y'ap fè. Men, moun ki mache dwat yo gen kè kontan, y'ap fè fèt.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 7, text = "Moun ki mache dwat konnen pou l' respekte dwa pòv malere. Men, mechan an pa konnen bagay konsa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 8, text = "Moun ki pa gen respè pou lòt ap mache simen kont nan tout peyi a. Men moun ki gen konprann konnen pou l' kontwole tèt li lè li fache.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 9, text = "Lè moun ki gen konprann al nan leta ak moun fou, fache pa fache anyen p'ap regle.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 10, text = "Depi yon moun serye, ansasen pa vle wè li. Men, moun ki mache dwat yo ap pwoteje l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 11, text = "Lè moun fou ankòlè, li di sa ki vin nan bouch li. Men, moun ki gen bon konprann kontwole bouch li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 12, text = "Lè yon chèf renmen tripotay, se mechan ase k'ap sèvi avè l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 13, text = "Gen yon bagay ni pòv la ni moun k'ap peze l' la gen ansanm: se Bondye ki bay ni yonn ni lòt je pou yo wè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 14, text = "Lè yon wa pran kòz malere yo pou l' defann dwa yo san patipri, wa sa a la pou l' gouvènen lontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 15, text = "Baton ki korije timoun ap ba yo konprann. Men, timoun yo kite fè sa yo pito gen pou fè manman yo wont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 16, text = "Lè mechan an rive chèf nan yon peyi, gen plis mechanste k'ap fèt. Men, moun k'ap mache dwat yo va wè jan mechan yo ap tonbe.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 17, text = "Korije pitit gason ou lan, li p'ap ba ou tèt chaje. L'a fè kè ou kontan.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 18, text = "Lè pa gen moun ki pou fè pèp la konnen sa pou l' fè, pèp la an debandad nèt. Men, ala bon sa bon pou moun k'ap fè sa lalwa mande!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 19, text = "Pale anpil p'ap korije esklav. Menm lè li konprann, se pa sa k'ap fè l' obeyi.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 20, text = "Gen plis espwa pou yon moun ki san konprann pase pou yon moun k'ap prese pale san kalkile.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 21, text = "Lè ou mou ak yon esklav depi li tou piti, rive yon lè l'ap konprann se pitit ou li ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 22, text = "Moun ki ankòlè fasil toujou ap fè bagay yo pa dwe fè. Moun ki gen san wo toujou nan goumen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 23, text = "Awogans fè moun pèdi pye. Men, y'ap respekte moun ki soumèt devan Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 24, text = "Moun ki konplis yon vòlò, se moun ki rayi tèt li. Si li denonse vòlò a, y'ap pini l'. Si li pa denonse l', madichon Bondye ap tonbe sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 25, text = "Si ou pè sa moun ap di, ou antrave. Men, si ou mete konfyans ou nan Seyè a, ou pa bezwen pè anyen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 26, text = "Anpil moun ap kouri dèyè favè chèf. Men, se Bondye k'ap jije tout moun san patipri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 29, verseNumber = 27, text = "Moun ki mache dwat pa vle wè mechan. Mechan pa vle wè moun k'ap mache dwat.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 1, text = "Men pawòl Agou, pitit Jake, moun peyi Masa. Men deklarasyon nonm lan te fè: Mwen bouke, Bondye! Mwen bouke, Bondye! Mwen pa kapab ankò!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 2, text = "Mwen sòt pase panyen pèsi. Se pa moun mwen ye. Mwen pa gen lespri tankou tout moun.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 3, text = "Mwen pa janm konnen sa ki rele konesans. Mwen pa konprann anyen nan bagay Bondye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 4, text = "Ki moun ki janm moute nan syèl, apre sa ki redesann sou latè? Ki moun ki janm ranmase van yo nan men l'? Ki moun ki janm mare dlo yo nan rad li? Ki moun ki fikse limit tè a? Ki jan li rele? Ki jan pitit li rele? Di m' non, si ou konnen?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 5, text = "Bondye toujou kenbe pawòl li. Li pwoteje tout moun ki mete konfyans yo nan li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 6, text = "Pa fè l' di sa li pa di. Si ou fè sa, l'a fè ou repwòch, l'a fè tout moun wè se mantò ou ye.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 7, text = "Bondye, se de bagay ase mwen mande ou: Tanpri, pa refize m' yo anvan mwen mouri.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 8, text = "Men yo: Pa kite m' bay manti pou m' twonpe moun. Pa fè m' ni rich ni pòv. Ban m' kantite manje mwen bezwen pou m' viv la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 9, text = "Si mwen gen twòp, m'a vire do ba ou, m'a di mwen pa konnen ki moun ou ye. Si mwen pa gen ase, m'a vòlò, m'a fè yo pase ou nan betiz.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 10, text = "Pa janm pale yon domestik mal devan mèt li. L'a madichonnen ou, l'a fè ou peye bouch ou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 11, text = "Gen yon kalite moun k'ap bay papa yo madichon, ki pa gen konsiderasyon pou manman yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 12, text = "Gen yon lòt kalite moun ki konprann yo nan kondisyon pou fè sèvis Bondye. Men, pi mal pase yo nanpwen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 13, text = "Gen yon lòt kalite moun ankò ki mete nan tèt yo yo pa kanmarad pesonn, wa pa kouzen yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 14, text = "Gen yon lòt kalite moun, se bèt nan bwa yo ye. Pou yo viv, y'ap devore malere yo, y'ap pwofite sou pòv yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 15, text = "Sansi gen de pitit fi: tou de gen menm non, yo rele: Ban mwen! Ban mwen! Gen twa bagay ki pa janm di ase. Sa m'ap di la a! Gen kat bagay ki pa janm di se kont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 16, text = "Men yo: Se peyi kote mò yo ye a, se fanm ki pa ka fè pitit, se tè a ki pa janm bwè kont dlo li, epi se dife. Bagay sa yo pa janm di ase.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 17, text = "Yon pitit ki pase papa l' nan betiz, ki pa respekte lòd manman l', chen gen pou devore kadav li nan raje, zwezo nan bwa va manje grenn je li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 18, text = "Gen twa bagay mwen pa janm ka konprann. Sa m'ap di la a! Gen kat bagay konsa.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 19, text = "Men yo: Se jan malfini plane nan syèl la, se jan koulèv mache sou wòch, se jan bato kouri sou lanmè, se jan gason ak fanm rive fè lamou.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 20, text = "Men ki jan fanm k'ap twonpe mari yo fè: Lè yo fin fè sa y'ap fè a, yo benyen byen pwòp, epi yo di: Mwen pa fè anyen ki mal.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 21, text = "Gen twa bagay ki fè latè tranble. Sa m'ap di la a! Gen kat bagay moun pa ka sipòte.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 22, text = "Men yo: Se yon esklav ki rive chèf, se yon moun sòt ki gen tou sa li bezwen,", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 23, text = "se yon fanm ki pa t' janm jwenn moun renmen l' epi ki resi mare yon nòs, se yon sèvant ki pran plas metrès li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 24, text = "Gen kat ti bèt sou latè, gen lespri pase yo nanpwen:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 25, text = "Se foumi: yo tou fèb, men yo pase tout sezon chalè ap fè pwovizyon mete la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 26, text = "Se chat mawon: yo pa pi fò pase sa. Men, yo fè kay yo nan twou wòch.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 27, text = "Se krikèt vèt: yo pa gen chèf, men yo mache pa bann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 28, text = "Se zandolit: ou ka pran yo nan men ou. Men, ou jwenn yo nan palè wa yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 29, text = "Gen twa bagay ki bèl lè y'ap mache. Sa m'ap di la a! Gen kat bagay ki gen bèl demach:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 30, text = "Se lyon, se li ki pi fò nan tout zannimo, li pa pè yo yonn.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 31, text = "Se bouk kabrit. Se chwal sele bride. Se wa lè y'ap mache devan lame yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 32, text = "Si ou te sòt jouk pou ou te rive fè grandizè, kalkile sou sa ou fè a: Pe bouch ou!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 30, verseNumber = 33, text = "Si ou bat lèt, l'ap fè bè. Si ou frape yon moun sou men l', l'ap senyen. Si ou nan pouse dife, ou nan gwo kont.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 1, text = "Men Pawòl wa Lemwèl, men konsèy manman l' te ba li:", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 2, text = "Kisa pou m' di ou, pitit mwen, pitit ki soti nan zantray mwen? Se mwen ki te mande Bondye pou l' ban mwen ou. Kisa pou m' di ou?", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 3, text = "Pa gaspiye kouray ou nan fanm. Veye zo ou ak fanm k'ap fè malè chèf yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 4, text = "Lemwèl monchè, yon wa pa fèt pou nan bwè bweson. Chèf pa fèt pou nan bwè gwòg.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 5, text = "Lè yo bwè konsa, yo bliye lòd yo te bay. Yo p'ap pran ka malere yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 6, text = "Se moun ki dekouraje ak lavi ki tonbe nan gwòg. Se moun ki gen gwo lapenn nan kè yo ki lage kò yo nan bweson.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 7, text = "Yo bwè pou yo bliye mizè yo, pou yo pa chonje lapenn yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 8, text = "Louvri bouch ou pale pou moun ki pa ka pale pou tèt yo. Defann kòz moun ki san sekou yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 9, text = "Pale pou yo. Pa fè patipri. Defann kòz malere yo ak endijan yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 10, text = "Sa pa fasil pou moun jwenn yon bon madanm. Lè li jwenn li, li gen plis valè pase yon boul lò.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 11, text = "Mari l' mete tout konfyans li nan li. Tout bagay ap mache byen lakay li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 12, text = "Madanm lan p'ap janm aji mal ak mari l', l'ap pase tout lavi l' ap fè l' byen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 13, text = "Li chache lenn mouton ak fil swa, li travay yo fè twal ak men l'.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 14, text = "Tankou bato k'ap pote machandiz, li al byen lwen chache manje mete nan kay la.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 15, text = "Solèy poko leve, li gen tan sou pye l', l'ap pare manje pou moun nan kay la. L'ap di sèvant yo sa pou yo fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 16, text = "Li fè lide sou yon tè, li achte l' ak lajan li fè ak men l'. Li fè jaden rezen sou li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 17, text = "Li mare ren l', li twouse manch rad li pou l' travay.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 18, text = "Li santi zafè l' ap mache byen, li rete byen ta lannwit ap travay.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 19, text = "Li file koton, li koud rad li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 20, text = "Li lonje men l' bay pòv. Li pran ka malere.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 21, text = "Li pa pè fredi pou moun lakay li, paske tout moun gen rad cho pou mete sou yo.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 22, text = "Li fè kouvèti lenn pou kabann yo. Tout rad li yo fèt ak twal wouj tise byen sere.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 23, text = "Mari l', se yonn nan chèf fanmi lavil la. Tout moun lavil la ap nonmen non l' an byen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 24, text = "Madanm li fe rad pou l' vann, li fè bèl senti, li vann yo ak machann.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 25, text = "Li gen anpil kouraj, tout moun respekte l', li pa pè denmen.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 26, text = "Lè li louvri bouch li, se bon konsèy li bay. Li toujou gen bon pawòl nan bouch li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 27, text = "Li konnen vire tounen tout moun nan kay la. Li toujou gen yon bagay l'ap fè.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 28, text = "Tout pitit li yo ap fè l' konpliman. Mari l' menm ap fè lwanj li.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 29, text = "L'ap di: Mwen konnen anpil madanm. Men ou menm, nanpwen tankou ou!", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 30, text = "Bèl fanm pa di bon madanm pou sa. Bèl figi pa la pou lontan. Men, y'a fè lwanj yon fanm ki gen krentif pou Seyè a.", bookId = 20),
        Verse(book = "Pwovèb", chapter = 31, verseNumber = 31, text = "Ba li sa ki pou li a. Lè y'a wè sa l' fè, se pou tout moun fè lwanj li.", bookId = 20)
